        patterns = [
            "invoice[ ]*inv[- ]*[0-9]+",
            "invoice[ ]*[0-9]+",
            "inv[- ]*[0-9]+",
            "inv[ ]*[0-9]+"
        ]
    else:
        patterns = [
            "document[ ]*doc[- ]*[0-9]+",
            "document[ ]*[0-9]+",
            "doc[- ]*[0-9]+",
            "doc[ ]*[0-9]+"
        ]

    ids = []
    for pattern in patterns:
        found = kit.find(pattern, text)
        for item in found:
            clean = normalizeId(item, kind)
            if clean != "" and clean not in ids:
